function renderAdventure(c){return syncNotice(c)+renderStudyExperience(c,studyExperience(c)==='guild'?'guild':'expedition');}

function visibleMicroLessons(){
  return CISA_MICROLESSONS.filter(l=>(!rt.domain||l.domainId===rt.domain||LESSONS.find(x=>x.id===(l.lessonId||l.id))?.domainId===rt.domain)&&(!rt.lessonQuery||JSON.stringify([l.title,l.concept]).toLowerCase().includes(rt.lessonQuery.toLowerCase())));
}
