function renderLessonIndex(available,id,c){
  return `<aside class="cq-lesson-index"><label><span class="label-title">Find a concept</span><input id="cqLessonSearch" type="search" value="${esc(rt.lessonQuery)}" placeholder="Search lessons"></label><select id="cqLessonDomain" aria-label="Lesson domain">${domainOptions(rt.domain)}</select><div class="cq-lesson-list">${available.map(l=>`<button class="${(l.lessonId||l.id)===id?'active':''}" data-cq-lesson="${l.lessonId||l.id}"><span>${esc(LESSONS.find(x=>x.id===(l.lessonId||l.id))?.domain||'')}</span>${esc(l.title)}${c.profile.v3.lessonProgress?.[l.lessonId||l.id]?' ✓':''}</button>`).join('')||'<p class="cq-fine">No matching concepts. Change the search or domain above.</p>'}</div></aside>`;
}
