function renderImportAudit(item,index){
 const audit=item.importAudit;if(!audit)return '';const matches=audit.matches||[],pages=Math.max(1,Math.ceil(matches.length/10)),page=Math.max(0,Math.min(pages-1,Number(item.auditPage)||0));
 const reference=ref=>`<li><strong>${esc(ref.scope||(/^guild_/.test(ref.scopeKey)?'Guild':/^personal_/.test(ref.scopeKey)?'Personal':'Public'))}</strong>${ref.lessonId?` · ${esc(ref.lessonId)}`:''}${ref.id?` · question <code>${esc(ref.id)}</code>`:' · earlier file in this batch'}${ref.scopeKey?`<small>Storage scope: ${esc(ref.scopeKey)}</small>`:''}<p>Answer: ${esc(ref.answer||'No answer key')}</p></li>`;
 return `<details class="cq-explain cq-import-audit" data-cq-audit-details="${index}" ${item.auditOpen?'open':''}><summary>Compare questions · ${audit.existingDuplicates||0} already uploaded · ${audit.batchDuplicates||0} repeated in this batch · ${audit.answerConflicts||0} answer conflicts</summary><p>${audit.newQuestions||0} new questions. Matching text and reordered choices are compared by their answer content. Questions with different keys remain separate for review.</p>${matches.slice(page*10,page*10+10).map(match=>`<details class="soft"><summary>${esc(match.question)}</summary>${match.existing?.length?`<h4>Already in your loaded library</h4><ul>${match.existing.map(reference).join('')}</ul>`:''}${match.batch?.length?`<h4>Also found in this batch</h4><ul>${match.batch.map(reference).join('')}</ul>`:''}${match.conflicts?.length?`<h4>Different answer key · review before sharing</h4><ul>${match.conflicts.map(reference).join('')}</ul>`:''}</details>`).join('')||'<p>No matching existing or earlier-batch questions.</p>'}${pages>1?`<div class="button-row"><button class="secondary-button small" data-cq-audit-page="${index}:${page-1}" ${page===0?'disabled':''}>Previous matches</button><span>Matches ${page*10+1}–${Math.min(matches.length,page*10+10)} of ${matches.length}</span><button class="secondary-button small" data-cq-audit-page="${index}:${page+1}" ${page>=pages-1?'disabled':''}>Next matches</button></div>`:''}</details>`;
}
