function bindFeedGestures(c){
  const cardElement=$('#cqStudyCard');if(!cardElement)return;
  let start=null;
  const blocked=target=>target.closest('button,a,input,select,textarea,summary,details,[contenteditable="true"],.cq-recall-result,.cq-coach-answer');
  const act=direction=>{
    if(rt.ratingBusy)return;
    if(direction==='right'&&!rt.revealed){const reveal=$('#cqReveal');if(reveal&&!reveal.disabled)reveal.click();}
    else if(direction==='left'&&rt.revealed){const card=feedCard(c);const isMc=Object.keys(card?.choices||{}).length>=2;const rating=isMc&&rt.choice!==card.correctAnswer?'Again':'Good';$(`[data-cq-rate="${rating}"]`)?.click();}
  };
  cardElement.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'||blocked(event.target)||event.clientX<24){start=null;return;}start={x:event.clientX,y:event.clientY,at:Date.now(),pointerId:event.pointerId};},{passive:true});
  cardElement.addEventListener('pointerup',event=>{if(!start||event.pointerId!==start.pointerId)return;const previous=start;start=null;const dx=event.clientX-previous.x,dy=event.clientY-previous.y;if(Date.now()-previous.at>900||Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.8||blocked(event.target))return;act(dx>0?'right':'left');},{passive:true});
  cardElement.addEventListener('pointercancel',()=>{start=null;},{passive:true});
  cardElement.addEventListener('keydown',event=>{if(event.target!==cardElement)return;if(event.key===' '&&!rt.pendingNext){event.preventDefault();act('right');}else if(['1','2','3','4'].includes(event.key)&&rt.revealed&&!rt.pendingNext){event.preventDefault();$(`[data-cq-rate="${['Again','Hard','Good','Easy'][Number(event.key)-1]}"]`)?.click();}else if(event.key==='Enter'&&rt.pendingNext){event.preventDefault();$('#cqNextQuestion')?.click();}else if(event.key==='ArrowRight'){event.preventDefault();act('right');}else if(event.key==='ArrowLeft'){event.preventDefault();act('left');}});
}
function speak(text,c){if(!window.speechSynthesis)return c.toast('Spoken audio is not available in this browser.');window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.rate=.95;window.speechSynthesis.speak(utterance);}
export function renderExperienceSettings(c){ensure(c);return `<section class="panel cq-settings"><p class="eyebrow">YOUR STUDY RHYTHM</p><h3>A small daily promise</h3><div class="form-grid"><label><span class="label-title">Questions per day</span><input id="cqDailyGoal" type="number" min="5" max="100" value="${c.profile.v3.dailyGoal||20}"></label></div><details class="cq-explain"><summary>Optional local AI coach and activity export</summary><div class="form-grid"><label><span class="label-title">Optional AI provider</span><select id="cqCoachProvider"><option value="ollama" ${c.profile.v3.coachProvider!=='browser'?'selected':''}>Ollama on this desktop</option><option value="browser" ${c.profile.v3.coachProvider==='browser'?'selected':''}>In-browser model (WebGPU)</option></select></label><label><span class="label-title">Local model name</span><input id="cqCoachModel" value="${esc(c.profile.v3.coachModel||'qwen3:0.6b')}"></label><label><span class="label-title">Ollama endpoint on this device</span><input id="cqCoachEndpoint" value="${esc(c.profile.v3.coachEndpoint||'http://localhost:11434')}"></label></div><label><input type="checkbox" id="cqCoachEnabled" ${c.profile.v3.coachEnabled?'checked':''}> Enable optional local coach</label><p class="helper">Daily recommendations work without AI. The optional coach uses your own Ollama install and downloaded open-weight model, with no hosted API charge. Ollama is a desktop localhost integration. The optional in-browser Qwen2.5 model runs on devices with WebGPU and enough memory (about 1 GB GPU memory plus model downloads); availability varies by phone and browser. Download it explicitly using the button below. Questions stay on your device. Model hardware, license, download and origin configuration still apply. AI explanations can be wrong; the imported answer rationale stays authoritative.</p><div class="button-row"><button class="secondary-button small" id="cqDownloadCoach">Download browser coach (~1 GB GPU memory)</button><button class="secondary-button small" id="cqExportActivity">Export study activity</button></div><p class="helper">The activity export contains event IDs and learning summaries without question text. Use your Todoist study task below for Everstead’s verified task rewards.</p></details><button class="primary-button small" id="cqSavePreferences">Save study preferences</button></section>`;}
export function bindExperienceSettings(c){$('#cqDownloadCoach')?.addEventListener('click',async()=>{const button=$('#cqDownloadCoach'),uid=c.user.uid;button.disabled=true;try{await prepareBrowserCoach(text=>{if(rt.uid===uid)button.textContent=text;});if(rt.uid!==uid)return;c.profile.v3.coachProvider='browser';c.profile.v3.coachEnabled=true;await c.save();button.textContent='Browser coach ready';$('#cqCoachProvider').value='browser';$('#cqCoachEnabled').checked=true;c.toast('Browser coach ready on this device.');}catch(error){button.textContent=error.message;c.toast(error.message,'error');}finally{button.disabled=false;}});$('#cqSavePreferences')?.addEventListener('click',async()=>{const goal=Number($('#cqDailyGoal').value);if(!Number.isInteger(goal)||goal<5||goal>100)return c.toast('Choose a daily goal between 5 and 100.','error');Object.assign(c.profile.v3,{dailyGoal:goal,coachEnabled:$('#cqCoachEnabled').checked,coachProvider:$('#cqCoachProvider').value,coachEndpoint:$('#cqCoachEndpoint').value.trim(),coachModel:$('#cqCoachModel').value.trim()||'qwen3:0.6b'});await c.save();c.toast('Study preferences saved.');});$('#cqExportActivity')?.addEventListener('click',()=>c.download('controlquest-study-activity.json',JSON.stringify(exportActivityJournal(c.profile.v3.activity,c.user.uid),null,2),'application/json'));}


function persistPocket(c){
  if(rt.uid!==c.user.uid||!rt.feedRun)return;
  const session={initialCount:rt.initialCount,timingKey:rt.timingKey||null,elapsedMs:rt.elapsedMs||0,timingTotal:rt.timingTotal||0,timingCount:rt.timingCount||0,choiceOrder:rt.choiceOrder||[],run:rt.feedRun,groupId:c.profile.activeGroupId||null,queue:rt.queue.map(card=>`${card.scopeKey}|${card.id}`),index:rt.index,choice:rt.choice,revealed:rt.revealed,domain:rt.domain,mode:rt.mode,assignmentLessonId:rt.assignmentLessonId||'',worldMode:rt.worldMode,interlude:!!rt.interlude,repeated:rt.repeated||{},skipGameTurns:!!rt.skipGameTurns,pendingNext:!!rt.pendingNext};
  c.profile.v3.pocketSession=session;try{localStorage.setItem(`cq-pocket-${c.user.uid}`,JSON.stringify(session));}catch{}
  c.saveQuiet?.();
}
